import classNames from 'classnames';
import React, { FC, ReactElement, useState } from 'react';
import { AlignEnum, SizeEnum, WeightEnum } from '../../types';
import ClickableDiv from '../clickableDiv';
import Text from '../text';
import './index.less';
import Tooltip from '../tooltip';

export interface GapCardProps {
  iconClass: string;
  title: string;
  description?: string;
  subHeader?: ReactElement<any, any>;
  /**
   * @param expanded value after toggle
   */
  onToggle?(expanded: boolean): void;
}

const GapCard: FC<GapCardProps> = ({
  children,
  title,
  description,
  iconClass,
  subHeader,
  onToggle,
}) => {
  const [expanded, setExpanded] = useState(false);

  const onClick = () => {
    const newExpanded = !expanded;
    onToggle?.(newExpanded);
    setExpanded(newExpanded);
  };

  return (
    <div className="gap-item" role="none">
      <ClickableDiv className="gap-title" onClick={onClick}>
        <Text size={SizeEnum['18px']} className={classNames('gap-title-main-icon', iconClass)} />
        <Text
          className="gap-title-text"
          weight={WeightEnum.semibold}
          size={SizeEnum['14px']}
          align={AlignEnum.left}
          text={title}
        />
        {description && (
          <Tooltip
            referenceClassName="gap-title-description-icon"
            placement="top"
            tooltipContent={description}
          >
            <Text className="icon-help" size={SizeEnum['14px']} />
          </Tooltip>
        )}
      </ClickableDiv>
      {subHeader}
      <div className={expanded ? 'gap-content-visible' : 'gap-content-hidden'}>
        <ClickableDiv className="icon-chevron-2 gap-arrow" onClick={onClick} />
        {children}
      </div>
    </div>
  );
};

export default GapCard;
